window.DEX_DATA["sources:backport-9d0a88f1653f7d68"]={"json":{"skins":[{"filename":"officerjenny.png"}],"names":[{"name":"君莎小姐"}],"chat":[{"lines":[{"text":"这些宝可梦都是你的吗？记得好好照顾它们！"},{"text":"我还会回来检查你有没有认真照顾宝可梦！"}]},{"lines":[{"text":"看见过火箭队吗？听说他们在附近出现过。"},{"text":"你在隔壁城镇看见火箭队了？好，谢谢！我马上去！"}]},{"lines":[{"text":"当心偷宝可梦的人，这一带最近有不少报案。"},{"text":"你不会也是宝可梦小偷吧？"}]},{"lines":[{"text":"我爱这份工作，能找到捣乱的人，把事情解决好！"},{"text":"小偷、骗子，还有各种坏蛋！君莎可不会放过你们！"}]}]}};
